import itertools

def eval_expr(expr, A, B):
    # expr as lambda
    return expr(A, B)

# define expressions
def expr1(A,B):
    return (not (A and B)) == ((not A) or (not B))
def expr2(A,B):
    return (not (A or B)) == ((not A) and (not B))
def expr3(A,B):
    # (A -> B) is (not A) or B
    return ((not A) or B) == ((not B) <= (not A))  # but need (¬B -> ¬A) = (B or ¬A)
def expr3_alt(A,B):
    return ((not A) or B) == (B or (not A))
def expr4(A,B):
    return ((not A) or B) == ((not A) or B)  # trivial?
def expr5(A,B):
    # (¬A -> B) = (A or B)
    # RHS: (A ∨ ¬B)
    return ((A) or B) == (A or (not B))
def expr6(A,B):
    # ¬(A -> B) = ¬((¬A) or B) = A and ¬B
    return (not ((not A) or B)) == (A and (not B))

def check(expr):
    for A,B in itertools.product([False,True],[False,True]):
        if not expr(A,B):
            return False
    return True

for i,expr in enumerate([expr1,expr2,expr3_alt,expr4,expr5,expr6], start=1):
    print(i, check(expr))

