import itertools

def equiv(expr1, expr2):
    # returns True if expr1 == expr2 for all combos
    for A,B in itertools.product([False,True],[False,True]):
        if expr1(A,B) != expr2(A,B):
            return False
    return True

def not_and(A,B):
    return not (A and B)
def notA_or_notB(A,B):
    return (not A) or (not B)

def not_or(A,B):
    return not (A or B)
def notA_and_notB(A,B):
    return (not A) and (not B)

def impl(X,Y):
    return (not X) or Y

def not_impl(A,B):
    return not impl(A,B)

# statements
s1 = equiv(lambda A,B: not_and(A,B), lambda A,B: notA_or_notB(A,B))
s2 = equiv(lambda A,B: not_or(A,B), lambda A,B: notA_and_notB(A,B))
s3 = equiv(lambda A,B: impl(A,B), lambda A,B: impl(not B, not A))
s4 = equiv(lambda A,B: impl(A,B), lambda A,B: (not A) or B)
s5 = equiv(lambda A,B: impl(not A, B), lambda A,B: A or (not B))
s6 = equiv(lambda A,B: not_impl(A,B), lambda A,B: A and (not B))

s1,s2,s3,s4,s5,s6

